const TZ = 'America/Sao_Paulo';
const pedido = $('Receber pedido').first().json;
const autor = pedido.autor || 'Daniel';
const numero = pedido.numero;
const linhas = n => { try { return $(n).all().map(i => i.json).filter(r => r && r.id !== undefined && r.id !== null); } catch (e) { return []; } };
const MESES = ['janeiro','fevereiro','março','abril','maio','junho','julho','agosto','setembro','outubro','novembro','dezembro'];
const cap = s => s ? s.charAt(0).toUpperCase() + s.slice(1) : s;
const BONITO = { alimentacao: 'Alimentação', educacao: 'Educação', saude: 'Saúde', vestuario: 'Vestuário', servicos: 'Serviços', transporte: 'Transporte', moradia: 'Moradia', lazer: 'Lazer', contas: 'Contas', assinaturas: 'Assinaturas', mercado: 'Mercado', outros: 'Outros', presentes: 'Presentes', viagem: 'Viagem', pets: 'Pets', beleza: 'Beleza', impostos: 'Impostos', investimentos: 'Investimentos' };
const nomeCat = c => { const k = String(c || 'outros').toLowerCase().trim(); return BONITO[k] || cap(k); };
const agora = DateTime.now().setZone(TZ);
let ini, fim, rotulo;
const p = String(pedido.periodo || 'mes').toLowerCase();
if (p === 'mes_passado') { ini = agora.minus({ months: 1 }).startOf('month'); fim = agora.startOf('month').minus({ milliseconds: 1 }); rotulo = cap(MESES[ini.month - 1]) + ' de ' + ini.year; }
else if (p === 'semana') { ini = agora.startOf('week'); fim = agora.endOf('day'); rotulo = 'Semana de ' + ini.toFormat('dd/LL') + ' a ' + agora.toFormat('dd/LL'); }
else if (p === 'ultimos_30' || p === '30d') { ini = agora.minus({ days: 29 }).startOf('day'); fim = agora.endOf('day'); rotulo = 'Últimos 30 dias'; }
else { ini = agora.startOf('month'); fim = agora.endOf('day'); rotulo = cap(MESES[agora.month - 1]) + ' de ' + agora.year; }

const milhar = s => { let o = ''; for (let i = 0; i < s.length; i++) { if (i > 0 && (s.length - i) % 3 === 0) o += '.'; o += s[i]; } return o; };
const brl = v => { const n = Math.abs(Number(v || 0)).toFixed(2).split('.'); return (Number(v) < 0 ? '-' : '') + 'R$ ' + milhar(n[0]) + ',' + n[1]; };
const semAcento = s => String(s || '').toLowerCase().normalize('NFD').replace(/[^a-z0-9 ]/g, '');
const forma = f => {
  const s = semAcento(f);
  if (!s.trim()) return 'Não informado';
  if (s.includes('cred')) return 'Cartão de crédito';
  if (s.includes('deb')) return 'Cartão de débito';
  if (s.includes('pix')) return 'Pix';
  if (s.includes('dinh') || s.includes('especie')) return 'Dinheiro';
  if (s.includes('boleto')) return 'Boleto';
  if (s.includes('cart')) return 'Cartão';
  return cap(String(f).trim().slice(0, 24));
};

const tx = linhas('Buscar transações')
  .filter(t => (t.autor || 'Daniel') === autor)
  .map(t => ({ ...t, dt: DateTime.fromISO(String(t.data || t.createdAt)).setZone(TZ), v: Number(t.valor) || 0 }))
  .filter(t => t.dt.isValid && t.dt >= ini && t.dt <= fim);
const desp = tx.filter(t => t.tipo !== 'receita');
const rec = tx.filter(t => t.tipo === 'receita');
const totD = desp.reduce((s, t) => s + t.v, 0);
const totR = rec.reduce((s, t) => s + t.v, 0);
if (!tx.length) {
  return [{ json: { vazio: true, numero, texto: 'Ainda não encontrei lançamentos seus em ' + rotulo + ', então não tem o que mostrar no dashboard. Assim que você registrar gastos, eu monto para você.' } }];
}
const agrupar = (lista, chave) => { const m = {}; for (const t of lista) { const k = chave(t); m[k] = (m[k] || 0) + t.v; } return Object.entries(m).sort((a, b) => b[1] - a[1]); };
let cats = agrupar(desp, t => nomeCat(t.categoria));
if (cats.length > 6) { const resto = cats.slice(5).reduce((s, c) => s + c[1], 0); cats = cats.slice(0, 5).concat([['Outras', resto]]); }
const pags = agrupar(desp, t => forma(t.forma_pagamento)).slice(0, 5);
const maiores = desp.slice().sort((a, b) => b.v - a.v).slice(0, 4);
const subs = linhas('Buscar assinaturas').filter(s => (s.autor || 'Daniel') === autor && s.ativo !== false)
  .map(s => ({ nome: String(s.nome || 'Assinatura'), mensal: (Number(s.valor) || 0) / (s.ciclo === 'anual' ? 12 : 1) }))
  .sort((a, b) => b.mensal - a.mensal);
const totSubs = subs.reduce((s, x) => s + x.mensal, 0);

const W = 1080, M = 54;
const NAVY = '#1B1F3B', GREEN = '#14B37D', INK = '#0B6E4D', ORANGE = '#FF8A3D', MUTED = '#6B6F85', TRACK = '#EFE5D2', RED = '#C8402F';
const D = [], T = [];
const rect = (x1, y1, x2, y2, color, r) => D.push({ c: color, a: Math.round(x1), b: Math.round(y1), e: Math.round(x2), f: Math.round(y2), r: r || 0 });
const txt = (t, x, y, size, color) => T.push({ t: String(t), s: size, k: color, x: Math.round(x), y: Math.round(y) });
const larg = (s, size) => { let w = 0; for (const c of String(s)) w += /[0-9$]/.test(c) ? .556 : /[.,: ]/.test(c) ? .278 : c === '%' ? .889 : c === '-' ? .333 : /[A-Z]/.test(c) ? .68 : /[a-z]/.test(c) ? .5 : .55; return w * size; };
const dir = (t, xr, y, size, color) => txt(t, xr - larg(t, size), y, size, color);
const corta = (s, max) => { s = String(s); return s.length > max ? s.slice(0, max - 1).trimEnd() + '…' : s; };
const pct = (v, tot) => tot > 0 ? Math.round(v / tot * 100) + '%' : '0%';

rect(0, 0, W, 150, NAVY, 0);
rect(M, 76, M + 9, 94, GREEN, 2); rect(M + 18, 64, M + 27, 94, GREEN, 2); rect(M + 36, 52, M + 45, 94, GREEN, 2);
txt('Dyno', M + 66, 94, 46, '#FFF6EA');
dir('Painel de ' + autor, W - M, 94, 24, '#C9CCDD');
txt('Dashboard financeiro · ' + rotulo, M, 132, 24, '#C9CCDD');

const kpis = [['GASTOS', brl(totD), NAVY], ['RECEITAS', brl(totR), NAVY], ['SALDO', brl(totR - totD), (totR - totD) >= 0 ? INK : RED]];
kpis.forEach((k, i) => { const x = M + i * 330; rect(x, 180, x + 312, 300, '#FFFFFF', 14); txt(k[0], x + 22, 216, 20, MUTED); txt(k[1], x + 22, 270, 38, k[2]); });

txt('ONDE VOCÊ MAIS GASTOU', M, 346, 20, INK);
const maxC = cats.length ? cats[0][1] : 1;
cats.forEach((c, i) => {
  const y = 378 + i * 58;
  txt(corta(c[0], 28), M, y + 24, 24, NAVY);
  dir(brl(c[1]) + '  ·  ' + pct(c[1], totD), W - M, y + 24, 24, NAVY);
  rect(M, y + 34, W - M, y + 44, TRACK, 5);
  rect(M, y + 34, M + Math.max(10, (W - 2 * M) * c[1] / maxC), y + 44, GREEN, 5);
});

const y2 = 378 + cats.length * 58 + 26;
txt('COMO VOCÊ PAGOU', M, y2, 20, INK);
txt('ASSINATURAS ATIVAS', 567, y2, 20, INK);
const r0 = y2 + 30;
const maxP = pags.length ? pags[0][1] : 1;
pags.forEach((c, i) => {
  const y = r0 + i * 56;
  txt(corta(c[0], 20), M, y + 22, 22, NAVY);
  dir(brl(c[1]) + ' · ' + pct(c[1], totD), 513, y + 22, 22, NAVY);
  rect(M, y + 30, 513, y + 39, TRACK, 4);
  rect(M, y + 30, M + Math.max(9, 459 * c[1] / maxP), y + 39, ORANGE, 4);
});
let hRight = 56;
if (!subs.length) { txt('Nenhuma assinatura cadastrada', 567, r0 + 22, 22, MUTED); }
else {
  const mostra = subs.slice(0, 4);
  mostra.forEach((s, i) => {
    const y = r0 + i * 56;
    txt(corta(s.nome, 20), 567, y + 22, 22, NAVY);
    dir(brl(s.mensal), W - M, y + 22, 22, NAVY);
    rect(567, y + 36, W - M, y + 37, TRACK, 0);
  });
  const yt = r0 + mostra.length * 56;
  txt(subs.length > 4 ? 'Total (' + subs.length + ' assinaturas)' : 'Total por mês', 567, yt + 22, 22, INK);
  dir(brl(totSubs), W - M, yt + 22, 22, INK);
  hRight = (mostra.length + 1) * 56;
}
const y3 = r0 + Math.max(pags.length * 56, hRight) + 30;

txt('MAIORES GASTOS', M, y3, 20, INK);
maiores.forEach((t, i) => {
  const y = y3 + 26 + i * 58;
  const cat = nomeCat(t.categoria);
  const desc = String(t.descricao || '').trim();
  const texto = desc ? (desc.length <= 26 ? desc + ' · ' + cat : corta(desc, 38)) : cat;
  txt(t.dt.toFormat('dd/LL'), M, y + 26, 22, MUTED);
  txt(texto, M + 90, y + 26, 24, NAVY);
  dir(brl(t.v), W - M, y + 26, 24, NAVY);
  rect(M, y + 42, W - M, y + 43, TRACK, 0);
});
const yF = y3 + 26 + maiores.length * 58 + 40;
txt('Gerado pelo Dyno em ' + agora.toFormat('dd/LL/yyyy HH:mm') + ' · com base nos lançamentos feitos por você', M, yF, 18, MUTED);
const altura = Math.min(1500, yF + 36);

while (D.length < 40) D.push({ c: '#00000000', a: 0, b: 0, e: 1, f: 1, r: 0 });
while (T.length < 60) T.push({ t: '.', s: 10, k: '#00000000', x: 0, y: 0 });
const NL = String.fromCharCode(10);
const caption = '📊 Seu dashboard — ' + rotulo + NL + 'Gastos: ' + brl(totD) + ' · Receitas: ' + brl(totR) + ' · Saldo: ' + brl(totR - totD);
return [{ json: { vazio: false, numero, caption, altura, d: D.slice(0, 40), t: T.slice(0, 60) } }];

const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const base = $('Montar dashboard').first().json;
return [{ json: { numero: base.numero, caption: base.caption, b64: buf.toString('base64') } }];
